240	  const parsed = validateDuelInputLog(log);
241	  if (!parsed.ok) throw new TypeError(`invalid duel input log: ${parsed.issues.join("; ")}`);
242	  const { movesetVersion, startFrame, inputs } = parsed.value;
243	  const version = config.moveset.version;
244	  if (movesetVersion !== version) throw new Error(`the log was recorded on moveset ${movesetVersion}, not ${version}`);
245	  if (initial.movesetVersion !== version) throw new Error(`the initial state runs on moveset ${initial.movesetVersion}, not ${version}`);
246	  if (initial.frame !== startFrame) throw new Error(`the log starts at frame ${startFrame}, the state is at frame ${initial.frame}`);
247	  let state = initial;
248	  for (const frameInputs of inputs) state = stepDuel(config, state, frameInputs);
249	  return { state, hash: hashState(state) };
250	}
251	export * from "./boxes.js";
252	export * from "./input.js";
253	export * from "./state.js";
254	export * from "./step.js";
255	export * from "./snapshot.js";
256	export * from "./replay.js";
257	export {
258	  DUEL_INPUT,
259	  DUEL_INPUT_MASK,
260	  MOVESET_VERSION,
261	  type DuelInputLog,
262	  type DuelMove,
263	  type DuelMoveset,
264	} from "@pirate-sea-race/content/moves";
265	export { hashState } from "../hash.js";
266	import { DUEL_INPUT, DUEL_INPUT_MASK } from "@pirate-sea-race/content/moves";
267	
268	/** Player one's and player two's input bits (`DUEL_INPUT`) for one frame. */
269	export type DuelInputs = readonly [number, number];
270	
271	/** Anything that is not a non-negative safe integer becomes neutral; undefined bits are dropped. */
272	export function sanitizeDuelInput(bits: number): number {
273	  return Number.isSafeInteger(bits) && bits >= 0 ? bits & DUEL_INPUT_MASK : 0;
274	}
275	
276	/**
277	 * Held directions as axes: `h` is -1 (left), 0 or 1 (right); `v` is -1 (down), 0 or 1 (up). Both directions of an
278	 * axis held together are neutral (§8), whatever order the keys went down in.
279	 */
280	export function directions(bits: number): { h: -1 | 0 | 1; v: -1 | 0 | 1 } {
281	  const left = (bits & DUEL_INPUT.left) !== 0;
282	  const right = (bits & DUEL_INPUT.right) !== 0;
283	  const up = (bits & DUEL_INPUT.up) !== 0;
284	  const down = (bits & DUEL_INPUT.down) !== 0;
285	  return { h: left === right ? 0 : right ? 1 : -1, v: up === down ? 0 : up ? 1 : -1 };
286	}
287	
288	/** The same input for a fighter on the mirrored side of the arena: left and right swap. */
289	export function mirrorDuelInput(bits: number): number {
290	  const clean = sanitizeDuelInput(bits);
291	  const left = clean & DUEL_INPUT.left;
292	  const right = clean & DUEL_INPUT.right;
293	  return (clean & ~(DUEL_INPUT.left | DUEL_INPUT.right)) | (left !== 0 ? DUEL_INPUT.right : 0) | (right !== 0 ? DUEL_INPUT.left : 0);
294	}
295	
296	/** Input bits from button and direction names, for scripts and tests: `duelInput("down", "heavy")`. */
297	export function duelInput(...names: readonly (keyof typeof DUEL_INPUT)[]): number {
298	  return names.reduce((bits, name) => bits | DUEL_INPUT[name], 0);
299	}
300	import type { Box } from "@pirate-sea-race/content/moves";
301	
302	/** A box in arena coordinates: the half-open ranges [x0, x1) × [y0, y1), in sub-pixels. */
303	export interface WorldBox {
304	  readonly x0: number;
305	  readonly x1: number;
306	  readonly y0: number;
307	  readonly y1: number;
308	}
309	
310	export type Facing = 1 | -1;
311	
312	/** Facing left mirrors a box about the origin: [x, x + w) becomes [-x - w, -x). */
313	export function mirrorBox(box: Box): Box {
314	  return { x: -box.x - box.w, y: box.y, w: box.w, h: box.h };
315	}
316	
317	/** A fighter-relative box (drawn facing right) placed at a fighter's origin and facing. */
318	export function worldBox(box: Box, x: number, y: number, facing: Facing): WorldBox {
319	  const placed = facing === 1 ? box : mirrorBox(box);
320	  return { x0: x + placed.x, x1: x + placed.x + placed.w, y0: y + placed.y, y1: y + placed.y + placed.h };
321	}
322	
323	/** Half-open boxes overlap only when they share an area: touching edges do not count. */
324	export function overlaps(a: WorldBox, b: WorldBox): boolean {
325	  return a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
326	}

