119	    ["projectile active frames", { ...jab, timing: { ...jab.timing, active: "projectile-life" } }, "timing.active"],
120	    ["more minus on block than active + recovery", { ...jab, timing: { ...jab.timing, onBlock: { kind: "frames", advantage: -16 } } }, "timing.onBlock.advantage"],
121	    ["blockstun that disagrees with the advantage", { ...jab, blockstun: 12 }, "blockstun"],
