238	/** A seeded pseudo-random fight that lasts the round: mostly movement and guard, with occasional one-frame attacks. */
239	function randomInputs(seed: number, frames: number): DuelInputs[] {
240	  let rng = seed;
241	  const draw = (bound: number) => {
242	    const drawn = nextInt(rng, bound);
243	    rng = drawn.state;
244	    return drawn.value;
245	  };
246	  const held = [0, 0];
247	  const left = [0, 0];
248	  const inputs: DuelInputs[] = [];
249	  for (let frame = 0; frame < frames; frame++) {
250	    for (const player of [0, 1] as const) {
251	      if (left[player] === 0) {
252	        // Player one starts on the left, so its back is left; player two's is right.
253	        const back = player === 0 ? I("left") : I("right");
254	        const forward = player === 0 ? I("right") : I("left");
255	        const moves = [0, back, back, back | I("down"), forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash"), I("left", "right")];
256	        const attacks = [I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy")];
257	        const attack = draw(100) < 12;
258	        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
259	        left[player] = attack ? 1 : 1 + draw(30);
260	      }
261	      left[player]!--;
262	    }
263	    inputs.push([held[0]!, held[1]!]);
264	  }
265	  return inputs;
266	}
